def main():
    html = INDEX.read_text(encoding="utf-8")
    n = 0
    for old, new in REPLACEMENTS:
        if old in html:
            html = html.replace(old, new)
            n += 1
    INDEX.write_text(html, encoding="utf-8")
    print(f"Applied {n} page replacements")

if __name__ == "__main__":
    main()
